import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

import { defineConfig } from 'astro/config';
import starlight from '@astrojs/starlight';
import react from '@astrojs/react';

/**
 * The sidebar (including every guide chapter) is generated by
 * scripts/build-content.mjs, which runs on `predev` and `prebuild`. Reading it
 * here keeps the sidebar and the generated content tree in step.
 */
const sidebar = JSON.parse(
  readFileSync(fileURLToPath(new URL('./src/data/sidebar.json', import.meta.url)), 'utf8'),
);

/**
 * GitHub Pages project site → https://ryantjx.github.io/cmfas-exams/
 *
 * `base` must match the repository name and is used by every internal link the
 * generator writes. If this is ever served from a user/org root site or a custom
 * domain, set `base` to '/' and `site` to that origin — and update `BASE` in
 * scripts/build-content.mjs to match.
 */
export default defineConfig({
  site: 'https://ryantjx.github.io',
  base: '/cmfas-exams',
  trailingSlash: 'always',
  integrations: [
    starlight({
      title: 'CMFAS Exams',
      description:
        'Study guides, chapter quizzes, daily quizzes and mock exams for RES 12B, FMRP and CM-SIP.',
      lastUpdated: false,
      pagination: true,
      pagefind: true,
      customCss: ['./src/styles/custom.css'],
      components: {
        // Replace Starlight's auto|light|dark dropdown with a light/dark toggle.
        ThemeSelect: './src/components/ThemeToggle.astro',
      },
      sidebar,
      head: [
        {
          tag: 'meta',
          attrs: {
            name: 'robots',
            content: 'noindex',
          },
        },
      ],
    }),
    react(),
  ],
});
